mapper.insert:
/* setFile */
INSERT INTO TM_FILEXM (
            ORIG_NAME
          , STOR_NAME
          , FILE_PATH
          , FILE_SIZE
          , MIME_TYPE
          , REGI_USER
          , REGI_DATE
) VALUES (  #{origName}
          , #{storName}
          , #{filePath}
          , #{fileSize}
          , #{mimeType}
          , #{regiUser,jdbcType=NUMERIC}
          , CURRENT_TIMESTAMP
)

mapper.select:

SELECT /* getActivePublicFileCount */
       COUNT(*)
  FROM TM_FILEXM F
 WHERE F.STOR_NAME = #{storName}
   AND F.FILE_PATH = #{filePath}
   AND (   EXISTS (
                   SELECT 1
                     FROM TM_USERXM P
                    WHERE P.PROF_NUMB = F.FILE_NUMB
                      AND P.USER_STAT = #{userStatActive}
               )
        OR EXISTS (
                   SELECT 1
                     FROM TM_USERXM B
                    WHERE B.BGIM_NUMB = F.FILE_NUMB
                      AND B.USER_STAT = #{userStatActive}
               )
       )

mapper.delete:
DELETE /* delFileIfUnreferenced */
  FROM TM_FILEXM
 WHERE FILE_NUMB = #{fileNumb}
   AND NOT EXISTS (
           SELECT 1
             FROM TM_USERXM U
            WHERE U.PROF_NUMB = #{fileNumb}
               OR U.BGIM_NUMB = #{fileNumb}
       )
